-- =============================================================================
--  vw_ticketsalesreport (Phase 2): classification driven by ticket_type_map.
--  --------------------------------------------------------------------------
--  * Home/Away/Other, Online/Walk-up, Season/Match all come from the per-fixture
--    mapping (dash_control admin). MAPPING-ONLY: a ticket type with no map row
--    is treated as Other and does NOT count toward Home/Away/Season/attendance.
--    A fixture with no mapping rows shows blank Home/Away/Season.
--  * AttendanceBase sums each mapped type's chosen basis (sold / checked-in /
--    exclude). ReportedCrowd (computed in ChatHubticketco.PopulateDataTable) =
--    AttendanceBase + fixture_admin.other_manual.
--  * Section (GroundArea) and turnstile (CheckedInOperator) columns are physical
--    facts and remain keyword/operator based.
--  * AwaySold is HARDCODED to 675 for ONE specific fixture only (TicketCo id
--    1163729); every other fixture uses the computed away figure.
--
--  Run after migration.sql + migration_admin.sql.
-- =============================================================================

CREATE OR REPLACE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vw_ticketsalesreport` AS
select sum((case when ((l.`CheckedInDate` is not null and l.`CheckedInDate` <> '') and (m.`tickettype` is null or m.`attendance` <> 'exclude')) then 1 else 0 end)) AS `TotalCheckedIn`,sum((case when ((m.`channel` = 'walkup') and (l.`CheckedInDate` is not null and l.`CheckedInDate` <> '')) then 1 else 0 end)) AS `WalkUpCheckedIn`,sum((case when (l.`GroundArea` like '%WALK-UP%' and (l.`CheckedInOperator` = '3299870' or l.`CheckedInOperator` = '3299872') and (l.`CheckedInDate` is not null and l.`CheckedInDate` <> '')) then 1 else 0 end)) AS `AwayWalkUpCheckedIn`,sum((case when (l.`GroundArea` like '%WALK-UP%' and (l.`CheckedInOperator` <> '3299870' or l.`CheckedInOperator` <> '3299872') and (l.`CheckedInDate` is not null and l.`CheckedInDate` <> '')) then 1 else 0 end)) AS `HomeWalkUpCheckedIn`,sum((case when ((m.`channel` = 'online') and ((m.`homeaway` = 'home') or (m.`homeaway` = 'away')) and (m.`tickettype` is null or m.`category` <> 'season') and (l.`CheckedInDate` is not null and l.`CheckedInDate` <> '')) then 1 else 0 end)) AS `OnlineCheckedIn`,sum((case when ((m.`channel` = 'online') and ((m.`homeaway` = 'home') or (m.`homeaway` = 'away')) and (m.`tickettype` is null or m.`category` <> 'season')) then 1 else 0 end)) AS `OnlineSold`,sum((case when ((m.`category` = 'season') and (l.`CheckedInDate` is not null and l.`CheckedInDate` <> '')) then 1 else 0 end)) AS `SeasonTicketsCheckedIn`,sum((case when (l.`TicketType` like '%comp%' and (l.`CheckedInDate` is not null and l.`CheckedInDate` <> '')) then 1 else 0 end)) AS `CompsCheckedIn`,sum((case when ((m.`homeaway` = 'away') and (l.`CheckedInDate` is not null and l.`CheckedInDate` <> '')) then 1 else 0 end)) AS `AwayCheckedIn`,sum((case when ((m.`homeaway` = 'home') and (l.`CheckedInDate` is not null and l.`CheckedInDate` <> '')) then 1 else 0 end)) AS `HomeCheckedIn`,(case when (cast(max(l.`fixtureid`) as unsigned) = 1163729) then 675 else sum((case when ((m.`homeaway` = 'away') and (m.`channel` = 'online') and (m.`tickettype` is null or m.`category` <> 'season')) then 1 else 0 end)) end) AS `AwaySold`,sum((case when ((m.`homeaway` = 'home') and (m.`channel` = 'online') and (m.`tickettype` is null or m.`category` <> 'season')) then 1 else 0 end)) AS `HomeSold`,(select coalesce(`other_manual`,0) from `fixture_admin` where `fixtureid` = (select `fixtureid` from `dashboard_current_fixture` limit 1)) AS `othersold`,sum((case when (l.`GroundArea` like '%SECTION 1 - BDS DIGITAL STAND%' and (l.`CheckedInDate` is not null and l.`CheckedInDate` <> '')) then 1 else 0 end)) AS `BDS1CheckedIn`,sum((case when (l.`GroundArea` like '%SECTION 2 - BDS DIGITAL STAND%' and (l.`CheckedInDate` is not null and l.`CheckedInDate` <> '')) then 1 else 0 end)) AS `BDS2CheckedIn`,sum((case when (l.`GroundArea` like '%SECTION 3 - BDS DIGITAL STAND%' and (l.`CheckedInDate` is not null and l.`CheckedInDate` <> '')) then 1 else 0 end)) AS `BDS3CheckedIn`,sum((case when (l.`GroundArea` like '%SECTION 4 - BDS DIGITAL STAND%' and (l.`CheckedInDate` is not null and l.`CheckedInDate` <> '')) then 1 else 0 end)) AS `BDS4CheckedIn`,sum((case when (l.`GroundArea` like '%SECTION 5 - BDS DIGITAL STAND%' and (l.`CheckedInDate` is not null and l.`CheckedInDate` <> '')) then 1 else 0 end)) AS `BDS5CheckedIn`,sum((case when (l.`GroundArea` like '%SECTION 6 - BDS DIGITAL STAND%' and (l.`CheckedInDate` is not null and l.`CheckedInDate` <> '')) then 1 else 0 end)) AS `BDS6CheckedIn`,sum((case when (l.`GroundArea` like '%SECTION 7 - BDS DIGITAL STAND%' and (l.`CheckedInDate` is not null and l.`CheckedInDate` <> '')) then 1 else 0 end)) AS `BDS7CheckedIn`,sum((case when (l.`GroundArea` like '%SECTION 8 - BDS DIGITAL STAND%' and (l.`CheckedInDate` is not null and l.`CheckedInDate` <> '')) then 1 else 0 end)) AS `BDS8CheckedIn`,sum((case when (l.`GroundArea` like '%SECTION 9 - BDS DIGITAL STAND%' and (l.`CheckedInDate` is not null and l.`CheckedInDate` <> '')) then 1 else 0 end)) AS `BDS9CheckedIn`,sum((case when (l.`GroundArea` like '%OAKBANK SERVICES TERRACE%' and (l.`CheckedInDate` is not null and l.`CheckedInDate` <> '')) then 1 else 0 end)) AS `OakbankCheckedIn`,sum((case when (l.`GroundArea` like '%TERREGLES STREET TERRACE%' and (l.`CheckedInDate` is not null and l.`CheckedInDate` <> '')) then 1 else 0 end)) AS `TerreglesCheckedIn`,sum((case when (l.`GroundArea` like '%SECTION 1 - MAIN STAND%' and (l.`CheckedInDate` is not null and l.`CheckedInDate` <> '')) then 1 else 0 end)) AS `Alpha1CheckedIn`,sum((case when (l.`GroundArea` like '%SECTION 2 - MAIN STAND%' and (l.`CheckedInDate` is not null and l.`CheckedInDate` <> '')) then 1 else 0 end)) AS `Alpha2CheckedIn`,sum((case when (l.`GroundArea` like '%SECTION 3 - MAIN STAND%' and (l.`CheckedInDate` is not null and l.`CheckedInDate` <> '')) then 1 else 0 end)) AS `Alpha3CheckedIn`,sum((case when (l.`GroundArea` like '%SECTION 4 - MAIN STAND%' and (l.`CheckedInDate` is not null and l.`CheckedInDate` <> '')) then 1 else 0 end)) AS `Alpha4CheckedIn`,sum((case when ((l.`CheckedInOperator` = '3169864') and (l.`CheckedInDate` is not null and l.`CheckedInDate` <> '')) then 1 else 0 end)) AS `AlphaTS1`,sum((case when ((l.`CheckedInOperator` = '3169868' or l.`CheckedInOperator` = '3169871') and (l.`CheckedInDate` is not null and l.`CheckedInDate` <> '')) then 1 else 0 end)) AS `AlphaTS2`,sum((case when ((l.`CheckedInOperator` = '3299860') and (l.`CheckedInDate` is not null and l.`CheckedInDate` <> '')) then 1 else 0 end)) AS `EncTS1`,sum((case when ((l.`CheckedInOperator` = '3299862' or l.`CheckedInOperator` = '3299865') and (l.`CheckedInDate` is not null and l.`CheckedInDate` <> '')) then 1 else 0 end)) AS `TerraceTS1`,sum((case when ((l.`CheckedInOperator` = '3299867' or l.`CheckedInOperator` = '3299868') and (l.`CheckedInDate` is not null and l.`CheckedInDate` <> '')) then 1 else 0 end)) AS `BDSTS1`,sum((case when ((l.`CheckedInOperator` = '3299870' or l.`CheckedInOperator` = '3299872') and (l.`CheckedInDate` is not null and l.`CheckedInDate` <> '')) then 1 else 0 end)) AS `BDSTS2`,max(l.`EventName`) AS `EventName`,sum((case when ((m.`category` = 'season')) then 1 else 0 end)) AS `SeasonTicketsSold`,sum((case when ((m.`channel` = 'walkup')) then 1 else 0 end)) AS `WalkUpSold`,sum((case when (l.`GroundArea` like '%SECTION 1 - BDS DIGITAL STAND%') then 1 else 0 end)) AS `BDS1Sold`,sum((case when (l.`GroundArea` like '%SECTION 2 - BDS DIGITAL STAND%') then 1 else 0 end)) AS `BDS2Sold`,sum((case when (l.`GroundArea` like '%SECTION 3 - BDS DIGITAL STAND%') then 1 else 0 end)) AS `BDS3Sold`,sum((case when (l.`GroundArea` like '%SECTION 4 - BDS DIGITAL STAND%') then 1 else 0 end)) AS `BDS4Sold`,sum((case when (l.`GroundArea` like '%SECTION 5 - BDS DIGITAL STAND%') then 1 else 0 end)) AS `BDS5Sold`,sum((case when (l.`GroundArea` like '%SECTION 6 - BDS DIGITAL STAND%') then 1 else 0 end)) AS `BDS6Sold`,sum((case when (l.`GroundArea` like '%SECTION 7 - BDS DIGITAL STAND%') then 1 else 0 end)) AS `BDS7Sold`,sum((case when (l.`GroundArea` like '%SECTION 8 - BDS DIGITAL STAND%') then 1 else 0 end)) AS `BDS8Sold`,sum((case when (l.`GroundArea` like '%SECTION 9 - BDS DIGITAL STAND%') then 1 else 0 end)) AS `BDS9Sold`,sum((case when (l.`GroundArea` like '%SECTION 1 - MAIN STAND%') then 1 else 0 end)) AS `Alpha1Sold`,sum((case when (l.`GroundArea` like '%SECTION 2 - MAIN STAND%') then 1 else 0 end)) AS `Alpha2Sold`,sum((case when (l.`GroundArea` like '%SECTION 3 - MAIN STAND%') then 1 else 0 end)) AS `Alpha3Sold`,sum((case when (l.`GroundArea` like '%SECTION 4 - MAIN STAND%') then 1 else 0 end)) AS `Alpha4Sold`,sum((case when (l.`GroundArea` like '%OAKBANK SERVICES TERRACE%') then 1 else 0 end)) AS `OakbankSold`,sum(1) AS `AllSold`,sum((case when ((l.`CheckedInDate` is not null and l.`CheckedInDate` <> '')) then 1 else 0 end)) AS `AllCheckedIn`,sum((case when ((m.`tickettype` is null or m.`homeaway` = 'na')) then 1 else 0 end)) AS `OtherBucketSold`,sum((case when (((m.`tickettype` is null or m.`homeaway` = 'na')) and (l.`CheckedInDate` is not null and l.`CheckedInDate` <> '')) then 1 else 0 end)) AS `OtherBucketCheckedIn`,sum((case when m.`tickettype` is null then 0 when m.`attendance` = 'sold' then 1 when m.`attendance` = 'checkedin' and (l.`CheckedInDate` is not null and l.`CheckedInDate` <> '') then 1 else 0 end)) AS `AttendanceBase` from `ticketco_matchsales_live` l left join `ticket_type_map` m on convert(m.`fixtureid` using utf8mb4) = convert(l.`fixtureid` using utf8mb4) and convert(m.`tickettype` using utf8mb4) = convert(l.`TicketType` using utf8mb4) where (l.`fixtureid` = (select `fixtureid` from `dashboard_current_fixture` limit 1));
